function value_changed(FRM,id)
{
	if (CheckIfHasHandler(id)) {dirty = 1};
	var funcs=null;
	if (validateById(FRM, id) != "") return;
	switch(id) {
		case "IsHTEnabled":
			funcs=new Array("ChannelBonding","UpperLowerChannelBonding","AMPDUMaxLength"); break;
		case "DBG":
			funcs=new Array("FixedHTRate"); break;
		case "AC_BK_CWmin_AP":
			funcs=new Array("AC_BK_CWmax_AP"); break;
		case "HiddenSSID":
			funcs=new Array("NonProc_WPS_ActivateWPS"); break;
		case "MSEC":
			funcs=new Array("NonProcSecurityMode","NonProc_WPA_Personal_Mode"); break;
		case "AC_BE_CWmin":
			funcs=new Array("AC_BE_CWmax"); break;
		case "ip_config_method":
			funcs=new Array("DHCPDEnabled"); break;
		case "11dActive":
			funcs=new Array("Country"); break;
		case "AC_BK_CWmin":
			funcs=new Array("AC_BK_CWmax"); break;
		case "ChannelBonding":
			funcs=new Array("FixedHTRate","Channel","UpperLowerChannelBonding"); break;
		case "NonProcSecurityMode":
			funcs=new Array("WepTxKeyIdx","NonProc_WepKeyLength","NonProc_Authentication","NonProc_WPA_Enterprise_Mode","NonProc_WPA_Personal_Mode","NonProc_WPA_Enterprise_Encapsulation","NonProc_WPA_Personal_Encapsulation","NonProc_WPA_Enterprise_Certificate","NonProc_WPS_ActivateWPS"); break;
		case "DHCPDEnabled":
			funcs=new Array("ip_config_method"); break;
		case "ShortCyclicPrefix":
			funcs=new Array("FixedHTRate"); break;
		case "Ignore11hConstraints":
			funcs=new Array("Channel"); break;
		case "Country":
			funcs=new Array("Channel"); break;
		case "UsePwrAmp":
			funcs=new Array("PowerSelection"); break;
		case "network_type":
			funcs=new Array("11hRadarDetect","HiddenSSID","OverlappingBSSProtection","APforwarding","ReliableMulticast","BasicRateSet","FixedRate","FixedHTRate","NonProcSecurityMode","NonProc_Authentication","NonProc_WPA_Personal_Mode","NonProc_WPA_Enterprise_Certificate","Country","FrequencyBand","NetworkMode","Channel","ChannelBonding","UpperLowerChannelBonding","RegulatoryDomain","BridgeMode","DHCPDEnabled","LoopBreakingEnabled","AC_BK_CWmin","AC_BK_CWmax","AC_BK_CWmin_AP","AC_BK_CWmax_AP","AC_BE_CWmin","AC_BE_CWmax","AC_BE_CWmin_AP","AC_BE_CWmax_AP","AC_VI_CWmin","AC_VI_CWmax","AC_VI_CWmin_AP","AC_VI_CWmax_AP","AC_VO_CWmin","AC_VO_CWmax","AC_VO_CWmin_AP","AC_VO_CWmax_AP","ChannelAnnouncementEnable","MSEC","L2NAT_DefHostManual","WPS_IgnoreSelectedRegistrar","DisconnectOnNACKs","NeverConnected","NonProc_WPS_ActivateWPS","NonProc_WPS_ApStatus","NonProc_WPS_StationStatus","Enrollee_type","NonProc_WPS_manualAPselection","AclMode"); break;
		case "HW_24G":
			funcs=new Array("FrequencyBand"); break;
		case "EEPROMCountryValid":
			funcs=new Array("Country"); break;
		case "NetworkMode":
			funcs=new Array("FixedRate","FixedHTRate"); break;
		case "HW_52G":
			funcs=new Array("FrequencyBand"); break;
		case "NonProc_WPS_StationStatus":
			funcs=new Array("Enrollee_type","NonProc_WPS_manualAPselection"); break;
		case "NonProc_WPS_ActivateWPS":
			funcs=new Array("HiddenSSID","NonProcSecurityMode","NonProc_WPS_ApStatus","NonProc_WPS_StationStatus","Enrollee_type","NonProc_WPS_manualAPselection"); break;
		case "BridgeMode":
			funcs=new Array("L2NAT_DefHostManual"); break;
		case "AC_BE_CWmin_AP":
			funcs=new Array("AC_BE_CWmax_AP"); break;
		case "FrequencyBand":
			funcs=new Array("11hRadarDetect","BasicRateSet","FixedRate","NetworkMode","Channel"); break;
	}
	for (var i = 0; funcs!=null && i < funcs.length; i ++) {
		if (isVisible(FRM, funcs[i])) {
			var opts = getopts(FRM,funcs[i]);
			refillComboGeneric(FRM,funcs[i],opts);
			validateById(FRM, funcs[i]);
		}
	}
	controlOnchange(FRM,id);
	updateSaveButton(FRM);
	refresh_Visible_ALL(FRM);
}

function controlOnchange(FRM,id)
{
	switch(id) {
		case "11hRadarDetect":
			if (getFrmVal(FRM,"11hRadarDetect")) getFrmElm(FRM,"Ignore11hConstraints").value = 0; else getFrmElm(FRM,"Ignore11hConstraints").value = 1;
			break;
		case "NonProcSecurityMode":
			if (getFrmElm(FRM,"NonProcSecurityMode").value == 2) getFrmElm(FRM,"WepEncryption").value = 1; else { getFrmElm(FRM,"WepEncryption").value = 0; getFrmElm(FRM,"Authentication").value = 0;}
			break;
		case "network_type":
			if (getFrmElm(FRM,"network_type").value == 0) getFrmElm(FRM,"Channel").value = 0;
			break;
		case "FrequencyBand":
			if (getFrmElm(FRM,"FrequencyBand").value==1) {if (getFrmElm(FRM,"network_type").value==2) {getFrmElm(FRM,"11hRadarDetect").value=0; getFrmElm(FRM,"Ignore11hConstraints").value=1; getFrmElm(FRM,"NetworkMode").value=23;} else {getFrmElm(FRM,"NetworkModeSTA").value=23;}} if (getFrmElm(FRM,"FrequencyBand").value==0) {if (getFrmElm(FRM,"network_type").value==2) getFrmElm(FRM,"NetworkMode").value=14; else {getFrmElm(FRM,"NetworkModeSTA").value=14;}} if (getFrmElm(FRM,"FrequencyBand").value==2) getFrmElm(FRM,"NetworkModeSTA").value=30;
			break;
		case "FrequencyBand_RO":
			if (getFrmElm(FRM,"FrequencyBand_RO").value==0) {if (getFrmElm(FRM,"network_type").value==0) getFrmElm(FRM,"NetworkModeSTA").value=14; else {getFrmElm(FRM,"NetworkMode").value=14;}}; if (getFrmElm(FRM,"FrequencyBand_RO").value==1) {if (getFrmElm(FRM,"network_type").value==0) getFrmElm(FRM,"NetworkModeSTA").value=23; else {getFrmElm(FRM,"NetworkMode").value=23;}}
			break;
		case "NetworkMode":
			if (getFrmElm(FRM,"NetworkMode").value==23 || getFrmElm(FRM,"NetworkMode").value==20 || getFrmElm(FRM,"NetworkMode").value==22 || getFrmElm(FRM,"NetworkMode").value==12 || getFrmElm(FRM,"NetworkMode").value==14) getFrmElm(FRM,"IsHTEnabled").value=1; else getFrmElm(FRM,"IsHTEnabled").value=0;value_changed(document.configuration_frm,"IsHTEnabled");
			break;
		case "ip_config_method":
			if (getFrmElm(FRM,"ip_config_method").value==0) getFrmElm(FRM,"DHCPDEnabled").value=0;
			break;
		case "DHCPDEnabled":
			if (getFrmElm(FRM,"DHCPDEnabled").value==1) { getFrmElm(FRM,"auto_network_type").value=0; getFrmElm(FRM,"ip_config_method").value=1; }
			break;
		case "AC_VO_UseAggregation":
			if (getFrmVal(FRM,"AC_VO_UseAggregation")) getFrmElm(FRM,"AC_VO_MaxNumOfPackets").value = 2;
			break;
		case "IsHTEnabled":
			if (getFrmElm(FRM,"IsHTEnabled").value == 0) getFrmElm(FRM,"ChannelBonding").value = 0;value_changed(document.configuration_frm,"ChannelBonding");
			break;
		case "PowerSelection_EDBOX":
			getFrmElm(FRM,"PowerSelection").value = getFrmVal(FRM,"PowerSelection_EDBOX");
			break;
		case "L2NAT_DefHostManual":
			if (getFrmElm(FRM,"L2NAT_DefHostManual").value == 0) getFrmElm(FRM,"L2NAT_DefHost").value = "00:00:00:00:00:00";
			break;
		case "NonProc_WPS_ActivateWPS":
			if (getFrmElm(FRM,"NonProc_WPS_ActivateWPS").value == 1) getFrmElm(FRM,"HiddenSSID").value = 0;
			break;
		default: break; 
	}
}

function updateSaveButton(FRM) {
	var visible = false; 
	switch(thisPageName) {
		case "Status And Statistics":
			if (0) visible=true;
			break;
		case "Administration Settings":
			if (0) visible=true;
			break;
		case "Security":
			if (getFrmVal(FRM,"network_type") == 2) visible=true;
			break;
		case "Wi-Fi Protected Setup":
			if (getParamChangesCount()!=0) visible=true;
			break;
		case "Access Control":
			if (0) visible=true;
			break;
		case "WPS Insert Parameters":
			if (0) visible=true;
			break;
		case "WPS Config Via PIN":
			if (0) visible=true;
			break;
		case "WPS Verify Parameters":
			if (0) visible=true;
			break;
		default:
			visible=true;
			break;
	}
	if (visible) showElement("SAVEBUTTON"); else hideElement("SAVEBUTTON");
}
